 10	public class Application {
 11	    public static void main(String[] args) {
 12	        String dbUrl = System.getenv("DB_URL");
 13	        String dbUser = System.getenv("DB_USER");
 14	        String dbPassword = System.getenv("DB_PASSWORD");
 15	        String portStr = System.getenv("PORT");
 16	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 17	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 18	
 19	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 20	            System.err.println("Error: DB_URL, DB_USER, and DB_PASSWORD environment variables are required");
 21	            System.exit(1);
 22	        }
 23	
 24	        Database db = new Database(dbUrl, dbUser, dbPassword);
 25	        MessageService messageService = new MessageService(testMode, true);
 26	        ReservationService reservationService = new ReservationService(db, messageService);
 27	        ReportService reportService = new ReportService(db);
 28	
 29	        Javalin app = Javalin.create();
 30	        ApiRoutes routes = new ApiRoutes(db, reservationService, reportService, messageService);
 31	        routes.register(app);
 32	
 33	        app.start(port);
 34	        System.out.println("Server running on port " + port);
 35	    }
 36	}
 37	package com.pousada.api;
 38	
 39	import com.google.gson.Gson;
 40	import com.google.gson.JsonObject;
 41	import com.pousada.db.Database;
 42	import com.pousada.models.Message;
 43	import com.pousada.models.Receipt;
 44	import com.pousada.models.Reservation;
 45	import com.pousada.models.Room;
 46	import com.pousada.services.MessageService;
 47	import com.pousada.services.ReportService;
 48	import com.pousada.services.ReservationService;
 49	import io.javalin.Javalin;
 50	
 51	import java.math.BigDecimal;
 52	import java.time.LocalDate;
 53	import java.time.YearMonth;
 54	import java.util.HashMap;
 55	import java.util.List;
 56	import java.util.Map;
 57	
 58	public class ApiRoutes {
 59	    private final Gson gson = new Gson();
 60	    private final ReservationService reservationService;
 61	    private final ReportService reportService;
 62	    private final MessageService messageService;
 63	
 64	    public ApiRoutes(Database db, ReservationService reservationService,
 65	                     ReportService reportService, MessageService messageService) {
 66	        this.reservationService = reservationService;
 67	        this.reportService = reportService;
 68	        this.messageService = messageService;
 69	    }
 70	
 71	    public void register(Javalin app) {
 72	        app.get("/rooms", ctx -> {
 73	            List<Map<String, Object>> rooms = new java.util.ArrayList<>();
 74	            for (Room room : Room.FIXED_ROOMS) {
 75	                Map<String, Object> roomMap = new HashMap<>();
 76	                roomMap.put("number", room.getNumber());
 77	                roomMap.put("type", room.getType().name());
 78	                roomMap.put("capacity", room.getCapacity());
 79	                roomMap.put("nightlyRate", room.getNightlyRate().doubleValue());
 80	                rooms.add(roomMap);
 81	            }
 82	            ctx.json(rooms);
 83	        });
 84	
 85	        app.post("/reservations", ctx -> {
 86	            try {
 87	                Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
 88	
 89	                int roomNumber = ((Double) body.get("roomNumber")).intValue();
 90	                String guestName = (String) body.get("guestName");
 91	                String guestEmail = (String) body.get("guestEmail");
 92	                String guestCpf = (String) body.get("guestCpf");
 93	                LocalDate checkIn = LocalDate.parse((String) body.get("checkIn"));
 94	                LocalDate checkOut = LocalDate.parse((String) body.get("checkOut"));
 95	                int guests = ((Double) body.get("guests")).intValue();
 96	                String ratePlan = (String) body.get("ratePlan");
 97	
 98	                Reservation reservation = reservationService.createReservation(
 99	                    roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan);
100	
101	                ctx.status(201);
102	                ctx.json(reservationToMap(reservation));
103	            } catch (Exception e) {
104	                handleError(ctx, e);
105	            }
106	        });
107	
108	        app.get("/reservations/{id}", ctx -> {
109	            try {
110	                long id = Long.parseLong(ctx.pathParam("id"));
111	                Reservation reservation = reservationService.getReservation(id);
112	                if (reservation == null) {
113	                    ctx.status(404);
114	                    ctx.json(errorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
115	                    return;
116	                }
117	                ctx.json(reservationToMap(reservation));
118	            } catch (NumberFormatException e) {
119	                ctx.status(400);
120	                ctx.json(errorResponse("INVALID_REQUEST", "Invalid reservation ID"));
121	            }
122	        });
123	
124	        app.post("/reservations/{id}/confirmation", ctx -> {
125	            try {
126	                long id = Long.parseLong(ctx.pathParam("id"));
127	                Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
128	                BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
129	
130	                Reservation reservation = reservationService.confirmReservation(id, amountPaid);
131	                ctx.json(reservationToMap(reservation));
132	            } catch (Exception e) {
133	                handleError(ctx, e);
134	            }
135	        });
136	
137	        app.post("/reservations/{id}/cancellation", ctx -> {
138	            try {
139	                long id = Long.parseLong(ctx.pathParam("id"));
140	                Reservation reservation = reservationService.cancelReservation(id);
141	                ctx.json(reservationToMap(reservation));
142	            } catch (Exception e) {
143	                handleError(ctx, e);
144	            }
145	        });
146	
147	        app.post("/reservations/{id}/check-in", ctx -> {
148	            try {
149	                long id = Long.parseLong(ctx.pathParam("id"));
150	                Reservation reservation = reservationService.checkIn(id);
151	                ctx.json(reservationToMap(reservation));
152	            } catch (Exception e) {
153	                handleError(ctx, e);
154	            }
155	        });
156	
157	        app.post("/reservations/{id}/check-out", ctx -> {
158	            try {
159	                long id = Long.parseLong(ctx.pathParam("id"));
160	                Receipt receipt = reservationService.checkOut(id);
161	                ctx.json(receiptToMap(receipt));
162	            } catch (Exception e) {
163	                handleError(ctx, e);
164	            }
165	        });
166	
167	        app.get("/reservations/{id}/document", ctx -> {
168	            try {
169	                long id = Long.parseLong(ctx.pathParam("id"));
170	                Receipt receipt = reservationService.getDocument(id);
171	                ctx.json(receiptToMap(receipt));
172	            } catch (Exception e) {
173	                handleError(ctx, e);
174	            }
175	        });
176	
177	        app.get("/messages", ctx -> {
178	            List<Map<String, Object>> messages = new java.util.ArrayList<>();
179	            for (Message msg : messageService.getMessages()) {
180	                Map<String, Object> msgMap = new HashMap<>();
181	                msgMap.put("id", msg.getId());
182	                msgMap.put("channel", msg.getChannel().name());
183	                msgMap.put("to", msg.getTo());
184	                msgMap.put("subject", msg.getSubject());
185	                msgMap.put("body", msg.getBody());
186	                msgMap.put("status", msg.getStatus().name());
187	                messages.add(msgMap);
188	            }
189	            ctx.json(messages);
190	        });
191	
192	        app.get("/reports/occupancy", ctx -> {
193	            try {
194	                String dateStr = ctx.queryParam("date");
195	                LocalDate date = LocalDate.parse(dateStr);
196	                String csv = reportService.getOccupancyReport(date);
197	                ctx.contentType("text/csv; charset=utf-8");
198	                ctx.result(csv);
199	            } catch (Exception e) {
200	                ctx.status(400);
201	                ctx.json(errorResponse("INVALID_REQUEST", "Invalid date format"));
202	            }
203	        });
204	
205	        app.get("/reports/revenue", ctx -> {
206	            try {
207	                String monthStr = ctx.queryParam("month");
208	                YearMonth.parse(monthStr);
209	                String csv = reportService.getRevenueReport(monthStr);
210	                ctx.contentType("text/csv; charset=utf-8");
211	                ctx.result(csv);
212	            } catch (Exception e) {
213	                ctx.status(400);
214	                ctx.json(errorResponse("INVALID_REQUEST", "Invalid month format"));
215	            }
216	        });
217	    }
218	
219	    private Map<String, Object> reservationToMap(Reservation res) {
220	        Map<String, Object> map = new HashMap<>();
221	        map.put("id", res.getId());
222	        map.put("roomNumber", res.getRoomNumber());
223	        map.put("guestName", res.getGuestName());
224	        map.put("guestEmail", res.getGuestEmail());
225	        map.put("guestCpf", res.getGuestCpf());
226	        map.put("checkIn", res.getCheckIn().toString());
227	        map.put("checkOut", res.getCheckOut().toString());
228	        map.put("guests", res.getGuests());
229	        map.put("ratePlan", res.getRatePlan().name());
230	        map.put("nights", res.getNights());
231	        map.put("subtotal", res.getSubtotal().doubleValue());
232	        map.put("discount", res.getDiscount().doubleValue());
233	        map.put("total", res.getTotal().doubleValue());
234	        map.put("status", res.getStatus().name());
235	        map.put("amountPaid", res.getAmountPaid().doubleValue());
236	        map.put("refund", res.getRefund() != null ? res.getRefund().doubleValue() : null);
237	        return map;
238	    }
239	
240	    private Map<String, Object> receiptToMap(Receipt receipt) {
241	        Map<String, Object> map = new HashMap<>();
242	        map.put("title", "Comprovante de reserva");
243	        map.put("reservationId", receipt.getReservationId());
244	        map.put("guestName", receipt.getGuestName());
245	        map.put("guestCpf", receipt.getGuestCpf());
246	        map.put("roomNumber", receipt.getRoomNumber());
247	        map.put("roomType", receipt.getRoomType());
248	        map.put("checkIn", receipt.getCheckIn().toString());
249	        map.put("checkOut", receipt.getCheckOut().toString());
250	        map.put("nights", receipt.getNights());
251	        map.put("subtotal", receipt.getSubtotal().doubleValue());
252	        map.put("discount", receipt.getDiscount().doubleValue());
253	        map.put("total", receipt.getTotal().doubleValue());
254	        return map;
255	    }
256	
257	    private Map<String, Object> errorResponse(String code, String message) {
258	        Map<String, Object> error = new HashMap<>();
259	        error.put("error", code);
260	        error.put("message", message);
261	        return error;
262	    }
263	
264	    private void handleError(io.javalin.http.Context ctx, Exception e) {
265	        String message = e.getMessage();
266	
267	        if (message == null || message.isEmpty()) {
268	            ctx.status(400);
269	            ctx.json(errorResponse("INVALID_REQUEST", "Invalid request"));
270	            return;
271	        }
272	
273	        switch (message) {
274	            case "ROOM_NOT_FOUND":
275	                ctx.status(404);
276	                ctx.json(errorResponse("ROOM_NOT_FOUND", "Room not found"));
277	                break;
278	            case "RESERVATION_NOT_FOUND":
279	                ctx.status(404);
280	                ctx.json(errorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
281	                break;
282	            case "ROOM_UNAVAILABLE":
283	                ctx.status(409);
284	                ctx.json(errorResponse("ROOM_UNAVAILABLE", "Room is unavailable for those dates"));
285	                break;
286	            case "CAPACITY_EXCEEDED":
287	                ctx.status(422);
288	                ctx.json(errorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
289	                break;
290	            case "OPERATION_NOT_ALLOWED":
291	                ctx.status(409);
292	                ctx.json(errorResponse("OPERATION_NOT_ALLOWED", "This operation is not allowed in the current state"));
293	                break;
294	            default:
295	                ctx.status(400);
296	                ctx.json(errorResponse("INVALID_REQUEST", message));
297	                break;
298	        }
299	    }
300	}

