 22	    public void sendMessage(String recipientEmail, String subject, String body) {
 23	        Message.Status status = Message.Status.SENT;
 24	        String finalEmail = recipientEmail;
 25	        String finalSubject = subject;
 26	        String finalBody = body;
 27	
 28	        if (!EmailValidator.isValid(recipientEmail)) {
 29	            status = Message.Status.BLOCKED;
 30	            addMessage(Message.Channel.EMAIL, recipientEmail, subject, body, status);
