 38	        }
 39	
 40	        addMessage(Message.Channel.EMAIL, finalEmail, finalSubject, finalBody, status);
 41	
 42	        if (!testMode && archiveEnabled && status == Message.Status.SENT) {
 43	            String archiveSubject = "[Cópia] " + subject;
 44	            addMessage(Message.Channel.EMAIL, ARCHIVE_EMAIL, archiveSubject, body, Message.Status.SENT);
 45	        }
 46	    }
