 66	package com.pousada.services;
 67	
 68	import com.pousada.db.Database;
 69	import com.pousada.models.Room;
 70	import com.pousada.models.Reservation;
 71	
 72	import java.math.BigDecimal;
 73	import java.time.LocalDate;
 74	import java.time.YearMonth;
 75	import java.util.HashMap;
 76	import java.util.Map;
 77	
 78	public class ReportService {
 79	    private final Database db;
 80	
 81	    public ReportService(Database db) {
 82	        this.db = db;
 83	    }
 84	
 85	    public String getOccupancyReport(LocalDate date) {
 86	        Map<Integer, Reservation> occupancy = db.getReservationsForNight(date);
 87	
 88	        StringBuilder csv = new StringBuilder();
 89	        csv.append("room,type,reservation,check_in,check_out\n");
 90	
 91	        for (Room room : Room.FIXED_ROOMS) {
 92	            Reservation reservation = occupancy.get(room.getNumber());
 93	            if (reservation != null) {
 94	                csv.append(room.getNumber()).append(",")
 95	                   .append(room.getType()).append(",")
 96	                   .append(reservation.getId()).append(",")
 97	                   .append(formatDate(reservation.getCheckIn())).append(",")
 98	                   .append(formatDate(reservation.getCheckOut())).append("\n");
 99	            }
100	        }
101	
102	        int occupiedRooms = occupancy.size();
103	        csv.append("total,").append(occupiedRooms).append("/5\n");
104	
105	        return csv.toString();
106	    }
107	
108	    public String getRevenueReport(String monthString) {
109	        YearMonth yearMonth = YearMonth.parse(monthString);
110	        LocalDate monthStart = yearMonth.atDay(1);
111	        LocalDate monthEnd = yearMonth.atEndOfMonth().plusDays(1);
112	
113	        java.util.List<Reservation> reservations = db.getReservationsForMonth(monthStart, monthEnd);
114	
115	        StringBuilder csv = new StringBuilder();
116	        csv.append("reservation,room,check_in,check_out,status,amount\n");
117	
118	        BigDecimal total = BigDecimal.ZERO;
119	
120	        for (Reservation res : reservations) {
121	            BigDecimal revenue = res.getAmountPaid();
122	            if (res.getRefund() != null) {
123	                revenue = revenue.subtract(res.getRefund());
124	            }
125	
126	            csv.append(res.getId()).append(",")
127	               .append(res.getRoomNumber()).append(",")
128	               .append(formatDate(res.getCheckIn())).append(",")
129	               .append(formatDate(res.getCheckOut())).append(",")
130	               .append(res.getStatus()).append(",")
131	               .append(formatMoney(revenue)).append("\n");
132	
133	            total = total.add(revenue);
134	        }
135	
136	        csv.append("total,,,,").append(formatMoney(total)).append("\n");
137	
138	        return csv.toString();
139	    }
140	
141	    private String formatDate(LocalDate date) {
142	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
143	    }
144	
145	    private String formatMoney(BigDecimal value) {
146	        return value.setScale(2, java.math.RoundingMode.HALF_UP).toString();
147	    }
148	}
149	package com.pousada.services;
150	
151	import com.pousada.db.Database;
152	import com.pousada.models.Receipt;
153	import com.pousada.models.Reservation;
154	import com.pousada.models.Room;
155	import com.pousada.utils.PriceCalculator;
156	
157	import java.math.BigDecimal;
158	import java.time.LocalDate;
159	
160	public class ReservationService {
161	    private final Database db;
162	    private final MessageService messageService;
163	
164	    public ReservationService(Database db, MessageService messageService) {
165	        this.db = db;
166	        this.messageService = messageService;
167	    }
168	
169	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
170	                                        LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan) {
171	        Room room = findRoom(roomNumber);
172	        if (room == null) {
173	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
174	        }
175	
176	        if (guests < 1 || guests > room.getCapacity()) {
177	            if (guests > room.getCapacity()) {
178	                throw new IllegalArgumentException("CAPACITY_EXCEEDED");
179	            } else {
180	                throw new IllegalArgumentException("INVALID_REQUEST");
181	            }
182	        }
183	
184	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
185	            throw new IllegalArgumentException("INVALID_REQUEST");
186	        }
187	
188	        if (db.isRoomOccupied(roomNumber, checkIn, checkOut)) {
189	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
190	        }
191	
192	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
193	        PriceCalculator.PriceBreakdown prices = PriceCalculator.calculate(
194	            room.getNightlyRate(), checkIn, checkOut, ratePlan);
195	
196	        Reservation reservation = new Reservation(
197	            0,
198	            roomNumber,
199	            guestName,
200	            guestEmail,
201	            guestCpf,
202	            checkIn,
203	            checkOut,
204	            guests,
205	            Reservation.RatePlan.valueOf(ratePlan),
206	            nights,
207	            prices.subtotal,
208	            prices.discount,
209	            prices.total,
210	            Reservation.Status.PENDING,
211	            BigDecimal.ZERO,
212	            null
213	        );
214	
215	        return db.saveReservation(reservation);
216	    }
217	
218	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) {
219	        Reservation reservation = db.getReservation(reservationId);
220	        if (reservation == null) {
221	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
222	        }
223	
224	        if (reservation.getStatus() != Reservation.Status.PENDING) {
225	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
226	        }
227	
228	        Reservation confirmed = reservation
229	            .withStatus(Reservation.Status.CONFIRMED)
230	            .withAmountPaid(amountPaid);
231	
232	        confirmed = db.updateReservation(confirmed);
233	
234	        Room room = findRoom(reservation.getRoomNumber());
235	        String roomTypeName = room.getType().name();
236	
237	        Receipt receipt = new Receipt(
238	            confirmed.getId(),
239	            confirmed.getGuestName(),
240	            confirmed.getGuestCpf(),
241	            confirmed.getRoomNumber(),
242	            roomTypeName,
243	            confirmed.getCheckIn(),
244	            confirmed.getCheckOut(),
245	            confirmed.getNights(),
246	            confirmed.getSubtotal(),
247	            confirmed.getDiscount(),
248	            confirmed.getTotal()
249	        );
250	
251	        String receiptText = receipt.format();
252	        String emailSubject = "Reserva confirmada - Pousada Maré Alta";
253	        String emailBody = "Olá, " + confirmed.getGuestName() + "!\n\n" +
254	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
255	            receiptText + "\n\n" +
256	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
257	            "Até breve!";
258	
259	        messageService.sendMessage(confirmed.getGuestEmail(), emailSubject, emailBody);
260	
261	        return confirmed;
262	    }
263	
264	    public Reservation checkIn(long reservationId) {
265	        Reservation reservation = db.getReservation(reservationId);
266	        if (reservation == null) {
267	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
268	        }
269	
270	        if (reservation.getStatus() != Reservation.Status.CONFIRMED) {
271	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
272	        }
273	
274	        return db.updateReservation(reservation.withStatus(Reservation.Status.CHECKED_IN));
275	    }
276	
277	    public Receipt checkOut(long reservationId) {
278	        Reservation reservation = db.getReservation(reservationId);
279	        if (reservation == null) {
280	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
281	        }
282	
283	        if (reservation.getStatus() != Reservation.Status.CHECKED_IN) {
284	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
285	        }
286	
287	        reservation = db.updateReservation(reservation.withStatus(Reservation.Status.CHECKED_OUT));
288	
289	        Room room = findRoom(reservation.getRoomNumber());
290	        String roomTypeName = room.getType().name();
291	
292	        return new Receipt(
293	            reservation.getId(),
294	            reservation.getGuestName(),
295	            reservation.getGuestCpf(),
296	            reservation.getRoomNumber(),
297	            roomTypeName,
298	            reservation.getCheckIn(),
299	            reservation.getCheckOut(),
300	            reservation.getNights(),
301	            reservation.getSubtotal(),
302	            reservation.getDiscount(),
303	            reservation.getTotal()
304	        );
305	    }
306	
307	    public Receipt getDocument(long reservationId) {
308	        Reservation reservation = db.getReservation(reservationId);
309	        if (reservation == null) {
310	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
311	        }
312	
313	        if (reservation.getStatus() != Reservation.Status.CONFIRMED &&
314	            reservation.getStatus() != Reservation.Status.CHECKED_IN &&
315	            reservation.getStatus() != Reservation.Status.CHECKED_OUT) {
316	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
317	        }
318	
319	        Room room = findRoom(reservation.getRoomNumber());
320	        String roomTypeName = room.getType().name();
321	
322	        return new Receipt(
323	            reservation.getId(),
324	            reservation.getGuestName(),
325	            reservation.getGuestCpf(),
326	            reservation.getRoomNumber(),
327	            roomTypeName,
328	            reservation.getCheckIn(),
329	            reservation.getCheckOut(),
330	            reservation.getNights(),
331	            reservation.getSubtotal(),
332	            reservation.getDiscount(),
333	            reservation.getTotal()
334	        );
335	    }
336	
337	    public Reservation cancelReservation(long reservationId) {
338	        Reservation reservation = db.getReservation(reservationId);
339	        if (reservation == null) {
340	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
341	        }
342	
343	        if (reservation.getStatus() != Reservation.Status.PENDING &&
344	            reservation.getStatus() != Reservation.Status.CONFIRMED) {
345	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
346	        }
347	
348	        BigDecimal refund = BigDecimal.ZERO;
349	        if (reservation.getStatus() == Reservation.Status.CONFIRMED) {
350	            if (reservation.getRatePlan() == Reservation.RatePlan.STANDARD) {
351	                refund = reservation.getAmountPaid();
352	            }
353	        }
354	
355	        return db.updateReservation(
356	            reservation.withStatus(Reservation.Status.CANCELLED).withRefund(refund)
357	        );
358	    }
359	
360	    public Reservation getReservation(long id) {
361	        return db.getReservation(id);
362	    }
363	
364	    private Room findRoom(int number) {
365	        for (Room room : Room.FIXED_ROOMS) {
366	            if (room.getNumber() == number) {
367	                return room;
368	            }
369	        }
370	        return null;
371	    }
372	}

