295	import java.math.BigDecimal;
296	import java.math.RoundingMode;
297	import java.time.LocalDate;
298	import java.time.YearMonth;
299	
300	public class PriceCalculator {
301	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
302	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
303	
304	    public static class PriceBreakdown {
305	        public final BigDecimal nightPrice;
306	        public final BigDecimal subtotal;
307	        public final BigDecimal discount;
308	        public final BigDecimal total;
309	
310	        public PriceBreakdown(BigDecimal nightPrice, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
311	            this.nightPrice = nightPrice;
312	            this.subtotal = subtotal;
313	            this.discount = discount;
314	            this.total = total;
315	        }
316	    }
317	
318	    private static BigDecimal roundHalfUp(BigDecimal value) {
319	        return value.setScale(2, RoundingMode.HALF_UP);
320	    }
321	
322	    private static boolean isHighSeason(LocalDate date) {
323	        YearMonth yearMonth = YearMonth.from(date);
324	        int month = date.getMonthValue();
325	
326	        if (month >= 12 || month <= 2) return true;
327	        if (month == 7) return true;
328	        return false;
329	    }
330	
331	    public static PriceBreakdown calculate(BigDecimal baseNightlyRate, LocalDate checkIn, LocalDate checkOut, String ratePlan) {
332	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
333	
334	        BigDecimal nightPrice = baseNightlyRate;
335	        LocalDate current = checkIn;
336	        BigDecimal subtotal = BigDecimal.ZERO;
337	
338	        for (int i = 0; i < nights; i++) {
339	            BigDecimal price = nightPrice;
340	            if (isHighSeason(current)) {
341	                price = price.multiply(HIGH_SEASON_MULTIPLIER);
342	            }
343	            price = roundHalfUp(price);
344	            subtotal = subtotal.add(price);
345	            current = current.plusDays(1);
346	        }
347	
348	        subtotal = roundHalfUp(subtotal);
349	
350	        BigDecimal discount;
351	        if ("NON_REFUNDABLE".equals(ratePlan)) {
352	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
353	            discount = roundHalfUp(discount);
354	        } else {
355	            discount = roundHalfUp(BigDecimal.ZERO);
356	        }
357	
358	        BigDecimal total = subtotal.subtract(discount);
359	        total = roundHalfUp(total);
360	
361	        return new PriceBreakdown(nightPrice, subtotal, discount, total);
362	    }
363	}

