183	            try (ResultSet rs = stmt.executeQuery()) {
184	                while (rs.next()) {
185	                    Reservation reservation = parseReservation(rs);
186	                    results.put(reservation.getRoomNumber(), reservation);
187	                }
188	            }
189	        } catch (SQLException e) {
