196	    public java.util.List<Reservation> getReservationsForMonth(LocalDate monthStart, LocalDate monthEnd) {
197	        String sql = """
198	            SELECT * FROM reservations
199	            WHERE (status = 'CONFIRMED' OR status = 'CHECKED_IN' OR status = 'CHECKED_OUT' OR status = 'CANCELLED')
200	            AND check_in >= ? AND check_in < ?
201	            ORDER BY check_in ASC, id ASC
202	            """;
203	
204	        java.util.List<Reservation> results = new java.util.ArrayList<>();
205	
206	        try (Connection conn = dataSource.getConnection();
207	             PreparedStatement stmt = conn.prepareStatement(sql)) {
208	            stmt.setDate(1, Date.valueOf(monthStart));
209	            stmt.setDate(2, Date.valueOf(monthEnd));
210	            try (ResultSet rs = stmt.executeQuery()) {
211	                while (rs.next()) {
212	                    Reservation reservation = parseReservation(rs);
213	                    if (reservation.getAmountPaid().signum() > 0) {
214	                        results.add(reservation);
215	                    }
216	                }
217	            }
218	        } catch (SQLException e) {
219	            throw new RuntimeException("Failed to get revenue", e);
220	        }
