252	public class EmailValidator {
253	    public static boolean isValid(String email) {
254	        if (email == null || email.isEmpty()) {
255	            return false;
256	        }
257	
258	        int atCount = 0;
259	        int atIndex = -1;
260	
261	        for (int i = 0; i < email.length(); i++) {
262	            if (email.charAt(i) == '@') {
263	                atCount++;
264	                atIndex = i;
265	            }
266	        }
267	
268	        if (atCount != 1) {
269	            return false;
270	        }
271	
272	        if (atIndex == 0 || atIndex == email.length() - 1) {
273	            return false;
274	        }
275	
276	        String domain = email.substring(atIndex + 1);
277	        int dotCount = 0;
278	        for (char c : domain.toCharArray()) {
279	            if (c == '.') dotCount++;
280	        }
281	
282	        if (dotCount == 0) {
283	            return false;
284	        }
285	
286	        if (domain.startsWith(".") || domain.endsWith(".")) {
287	            return false;
288	        }
289	
290	        return true;
291	    }
292	}
